import React from 'react';
import { Alert } from '../common/Alert';
import { parseMatrixText } from '../../utils/matrixParser';

interface MatrixTextInputProps {
    n: number;
    value: string;
    onChange: (text: string) => void;
    onSync: () => void;
}

export const MatrixTextInput: React.FC<MatrixTextInputProps> = ({
                                                                    n, value, onChange, onSync
                                                                }) => {
    const [error, setError] = React.useState<string>('');
    const [showExample, setShowExample] = React.useState<boolean>(false);

    const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        onChange(e.target.value);
        setError('');
    };

    const handleParse = () => {
        try {
            const result = parseMatrixText(value);
            if (result.n > 20) {
                setError('Размерность матрицы не должна превышать 20');
                return;
            }
            onSync();
            setError('');
            setShowExample(false);
        } catch (err) {
            setError((err as Error).message);
        }
    };

    const loadExample = () => {
        const exampleText = `3
2 1 -1 8
-3 -1 2 -11
-2 1 2 -3`;
        onChange(exampleText);
        setShowExample(true);
    };

    return (
        <div className="space-y-4">
            <div className="flex items-center justify-between">
                <label className="block text-sm font-medium text-gray-700">
                    Введите расширенную матрицу:
                </label>
                <button
                    onClick={loadExample}
                    className="text-sm text-blue-600 hover:text-blue-800"
                >
                    Пример
                </button>
            </div>

            {showExample && (
                <div className="bg-blue-50 border border-blue-200 rounded-md p-3 text-sm">
                    <p className="font-medium text-blue-700 mb-1">Формат ввода:</p>
                    <p className="text-blue-600 font-mono text-xs">
                        [размерность n]<br />
                        a₁₁ a₁₂ ... a₁ₙ b₁<br />
                        a₂₁ a₂₂ ... a₂ₙ b₂<br />
                        ...<br />
                        aₙ₁ aₙ₂ ... aₙₙ bₙ
                    </p>
                </div>
            )}

            <textarea
                value={value}
                onChange={handleTextChange}
                rows={n + 2}
                className="w-full px-3 py-2 border border-gray-300 rounded-md font-mono text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                placeholder={`${n}\n1 2 3 ${n+4}\n2 3 1 ${n+4}\n3 2 1 ${n+4}`}
                spellCheck={false}
            />

            {error && (
                <Alert type="error" message={error} />
            )}

            <div className="flex gap-2">
                <button
                    onClick={handleParse}
                    className="flex-1 bg-green-600 text-white rounded-md hover:bg-green-700 transition-colors py-2"
                >
                    Применить к таблице
                </button>
            </div>

            <p className="text-xs text-gray-500">
                * Изменения в таблице автоматически обновляют текст<br />
                * Чтобы применить текст к таблице, нажмите "Применить к таблице"
            </p>
        </div>
    );
};
